type record R1 {
     integer f1,
     integer f2
  }
  type union U {
     integer c1,
     R1   c2
  }
  type record R2 {
     integer g1,
     U    g2 optional
  }
  :
  var template R2 v_t1 := {
     g1 := 5,
     g2 := *
  }
  var template integer v_t2;
  v_t1.g2.f1 := 1;
     // after the assignment v_t2.g2 is { g2 := { f1 := 1, f2 := ? } }
  v_t1.g2 := omit;
  v_t2 := v_t1.g2.c1;
     // causes an error as omit is assigned to v_t1.g2
  var template U v_u := {c1 := omit}; //causes an error as union alternatives can not be omitted
  var template U v_u2 := omit; // after the assignment v_u2 will be omit

