type map from charstring to integer TMap;
     :
     var template TMap v_map;
     var template integer v_int;
     v_map := ({["id"] := 1}, {["id"] := ?, ["active"] := 1});
     v_int := v_map [0];
    // shall cause an error as template list is assigned to v_map

type map from charstring to integer TMap;
     :
     var template TMap v_map;
     var template integer v_int;
     :
     v_map := ?;
     v_int := v_map["test"];
     // after the assignment v_int will be AnyValueOrNone(*)
     v_map["test"] := 2;
     // after the assignment v_map will be { *, ["test"] := 2 }

